CREATE TABLE proveedores (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, codigo VARCHAR(30) NOT NULL, razon_social VARCHAR(180) NOT NULL, ruc VARCHAR(11), telefono VARCHAR(20), email VARCHAR(150), direccion VARCHAR(255), activo BOOLEAN NOT NULL DEFAULT TRUE,
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT uq_proveedores_codigo UNIQUE(codigo), CONSTRAINT uq_proveedores_ruc UNIQUE(ruc)
);
CREATE TABLE ordenes_compra (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, numero VARCHAR(30) NOT NULL, proveedor_id BIGINT NOT NULL REFERENCES proveedores(id), almacen_id BIGINT NOT NULL REFERENCES almacenes(id), estado VARCHAR(20) NOT NULL DEFAULT 'BORRADOR', fecha TIMESTAMPTZ NOT NULL DEFAULT now(), observaciones TEXT, total NUMERIC(14,2) NOT NULL DEFAULT 0,
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT uq_ordenes_compra_numero UNIQUE(numero), CONSTRAINT chk_orden_estado CHECK(estado IN ('BORRADOR','CONFIRMADA','RECIBIDA','ANULADA'))
);
CREATE TABLE orden_compra_detalles (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, orden_id BIGINT NOT NULL REFERENCES ordenes_compra(id), producto_id BIGINT NOT NULL REFERENCES productos(id), cantidad NUMERIC(14,3) NOT NULL CHECK(cantidad > 0), costo_unitario NUMERIC(14,2) NOT NULL CHECK(costo_unitario >= 0), cantidad_recibida NUMERIC(14,3) NOT NULL DEFAULT 0 CHECK(cantidad_recibida >= 0), subtotal NUMERIC(14,2) NOT NULL,
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE recepciones_compra (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, orden_id BIGINT NOT NULL REFERENCES ordenes_compra(id), numero VARCHAR(30) NOT NULL, fecha TIMESTAMPTZ NOT NULL DEFAULT now(), observaciones TEXT,
 creado_por VARCHAR(100) NOT NULL DEFAULT 'sistema', creado_en TIMESTAMPTZ NOT NULL DEFAULT now(), modificado_por VARCHAR(100), modificado_en TIMESTAMPTZ, version BIGINT NOT NULL DEFAULT 0, eliminado BOOLEAN NOT NULL DEFAULT FALSE,
 CONSTRAINT uq_recepciones_numero UNIQUE(numero)
);
CREATE TABLE recepcion_detalles (
 recepcion_id BIGINT NOT NULL REFERENCES recepciones_compra(id), detalle_orden_id BIGINT NOT NULL REFERENCES orden_compra_detalles(id), cantidad NUMERIC(14,3) NOT NULL CHECK(cantidad > 0), PRIMARY KEY(recepcion_id,detalle_orden_id)
);
